 @override void paint(Canvas c,Size z){final d=math.min(z.width,z.height);c.save();c.translate((z.width-d)/2,(z.height-d)/2);c.scale(d/100,d/100);c.drawShadow(Path()..addOval(const Rect.fromLTWH(15,79,70,6)),Colors.black.withValues(alpha:.14),4,false);switch(foodId){case 'bahraini_muhammar':c.drawOval(const Rect.fromLTWH(18,55,64,22),f(const Color(0xFF9C6A43)));c.drawOval(const Rect.fromLTWH(21,45,58,22),f(const Color(0xFFB97843)));for(final p in <Offset>[Offset(31,52),Offset(40,48),Offset(50,54),Offset(61,49),Offset(70,54)])c.drawCircle(p,2,f(const Color(0xFF6E402C)));c.drawArc(const Rect.fromLTWH(29,34,42,18),.2,2.7,false,s(const Color(0xFFD8A23B),4));break;case 'bahraini_mumawwash':c.drawOval(const Rect.fromLTWH(18,55,64,22),f(const Color(0xFFB98248)));c.drawOval(const Rect.fromLTWH(21,44,58,23),f(const Color(0xFFD8B66A)));for(final p in <Offset>[Offset(30,50),Offset(38,57),Offset(47,48),Offset(55,56),Offset(64,49),Offset(70,57)])c.drawCircle(p,2.4,f(const Color(0xFF71824B)));c.drawArc(const Rect.fromLTWH(35,39,30,18),3.3,2.5,false,s(const Color(0xFFD86A52),3));break;case 'bahraini_halwa':c.drawRRect(RRect.fromRectAndRadius(const Rect.fromLTWH(24,39,52,36),const Radius.circular(8)),f(const Color(0xFFB14F36)));c.drawRRect(RRect.fromRectAndRadius(const Rect.fromLTWH(29,43,42,27),const Radius.circular(6)),f(const Color(0xFFC86745)));for(final p in <Offset>[Offset(35,49),Offset(47,55),Offset(60,48),Offset(65,61),Offset(40,64)])c.drawOval(Rect.fromCenter(center:p,width:6,height:3),f(const Color(0xFFE9C27A)));break;}c.restore();}
 @override bool shouldRepaint(covariant FoodPictogramPainterBatch34 o)=>o.foodId!=foodId;
